examples.template:
MonarchCard(elevated = true) {
    Row(
        horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        MonarchAvatar(image = null, name = {{caller}}, size = MonarchAvatarSize.Md)
        Column(modifier = Modifier.weight(1f)) {
            MonarchText(text = {{caller}}, style = MonarchTextStyle.BodyStrong)
            Row(
                horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                MonarchIcon(SampleIcons.Call, contentDescription = null, size = MonarchIconSize.Sm)
                MonarchText(text = {{status}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
            }
            MonarchText(text = {{detail}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
        }
        MonarchIconButton(
            label = "Decline",
            onClick = {},
            variant = MonarchButtonVariant.Danger,
            shape = CircleShape,
        ) { MonarchIcon(SampleIcons.CallEnd, contentDescription = null) }
        MonarchIconButton(
            label = "Answer",
            onClick = {},
            variant = MonarchButtonVariant.Success,
            shape = CircleShape,
        ) { MonarchIcon(SampleIcons.Call, contentDescription = null) }
    }
}

